begin
 insert into ml_authoring.gateway_keys(key_hash) values(encode(sha256(convert_to(k,'UTF8')),'hex'));
 begin perform ml_systems.gateway('invalid','list','{}');raise exception 'Invalid gateway accepted';exception when insufficient_privilege then null;end;
 r:=ml_systems.gateway(k,'save',jsonb_build_object('id',p->>'id','version',0,'data',p));
 if r->>'version'<>'1' then raise exception 'Save failed';end if;
 begin perform ml_systems.gateway(k,'save',jsonb_build_object('id',p->>'id','version',0,'data',p));raise exception 'Stale save accepted';exception when serialization_failure then null;end;
 r:=ml_systems.gateway(k,'get',jsonb_build_object('id',p->>'id'));if r->'data' is distinct from p then raise exception 'Source did not roundtrip';end if;
 perform ml_systems.gateway(k,'session-create',jsonb_build_object('id',p->>'id','session',sess,'room',room));
 r:=ml_systems.gateway(k,'session-get',jsonb_build_object('room',room));if r->>'version'<>'1' or r::text like '%token_hash%' then raise exception 'Guest read failed';end if;
 perform ml_systems.gateway(k,'session-join',jsonb_build_object('room',room,'name','QA Learner','team','A','member',member,'proof',proof));
 begin perform ml_systems.gateway(k,'session-save',jsonb_build_object('room',room,'member',member,'proof',repeat('0',48),'version',1,'data',p));raise exception 'Wrong proof accepted';exception when insufficient_privilege then null;end;
 r:=ml_systems.gateway(k,'session-save',jsonb_build_object('room',room,'member',member,'proof',proof,'version',1,'data',p));if r->>'version'<>'2' then raise exception 'Student save failed';end if;
 perform ml_systems.gateway(k,'session-settings',jsonb_build_object('id',p->>'id','session',sess,'locked',true,'minutes',5));
 begin perform ml_systems.gateway(k,'session-save',jsonb_build_object('room',room,'member',member,'proof',proof,'version',2,'data',p));raise exception 'Locked edit accepted';exception when insufficient_privilege then null;end;
 perform ml_systems.gateway(k,'session-reflect',jsonb_build_object('room',room,'member',member,'proof',proof,'reflection','Feedback amplifies fatigue.'));
 r:=ml_systems.gateway(k,'session-roster',jsonb_build_object('id',p->>'id','session',sess));if jsonb_array_length(r)<>1 or r->0->>'contributions'<>'1' or r->0->>'reflection'<>'Feedback amplifies fatigue.' or r::text like '%proof_hash%' then raise exception 'Participation report failed';end if;
 r:=ml_systems.gateway(k,'history',jsonb_build_object('id',p->>'id'));if jsonb_array_length(r)<>1 then raise exception 'History failed';end if;
 perform ml_systems.gateway(k,'session-settings',jsonb_build_object('id',p->>'id','session',sess,'active',false));
 begin perform ml_systems.gateway(k,'session-get',jsonb_build_object('room',room));raise exception 'Revoked link accepted';exception when no_data_found then null;end;
 perform ml_systems.gateway(k,'archive',jsonb_build_object('id',p->>'id'));
 begin perform ml_systems.gateway(k,'get',jsonb_build_object('id',p->>'id'));raise exception 'Archived source returned';exception when no_data_found then null;end;
end;
